        int rawStaartAanneemsomRijNr = RawStaartAanneemsomRijNr();
        return
           rijNr == rawStaartAanneemsomRijNr ||
           (m_RawBlancoStaartbladRijNr >= 0 &&
             rijNr == rawStaartAanneemsomRijNr + (AantalRijen() - m_RawBlancoStaartbladRijNr));
    }
    /// <summary>Bereken het rijnummer van de eerste van de extra regels aan het eind van de RAW-inschrijfstaat</summary>
    /// <returns>Een rijnummer</returns>
    private int RawStaartAanneemsomRijNr()
    {
        return m_AantalTabelRijen + ((m_RawEenmaligeKostenRijNr >= 0) ? 1 : 0) + ((m_SubTotaalRijNr >= 0) ? 1 : 0);

    }
    private double RawBerekenAanneemsom()
    {
        if (m_BgrBladTabel != null)
        {
            string stuurcode;
            for (int rijNr = m_BgrBladTabel.AantalRijen() - 1; rijNr >= 0; rijNr--)
            {
                stuurcode = m_BgrBladTabel.VeldString((int)BBgrBladRegel.EBbdGegeven.stk, rijNr);
                if (!string.IsNullOrEmpty(stuurcode) &&
                   stuurcode[0] == BBgrBldFieTot.c_Stk)
                {
                    return m_BgrBladTabel.VeldDouble((int)BBgrBladRegel.EBbdGegeven.ttg, rijNr, out bool geenWaarde);
                }
            }
        }
        return 0.0;
    }

    public int RawInschrijvers(int rijNr)
    {
        int aantalInschrijvers = 0;
        if (rijNr - RawStaartAanneemsomRijNr() == 6)
        {
            if (!String.IsNullOrEmpty(_Begroting._RawInfo.RawStringGegeven(BRawInfo.ERawGegeven.Inschrijver1)))
                aantalInschrijvers++;
            if (!String.IsNullOrEmpty(_Begroting._RawInfo.RawStringGegeven(BRawInfo.ERawGegeven.Inschrijver2)))
                aantalInschrijvers++;
            if (!String.IsNullOrEmpty(_Begroting._RawInfo.RawStringGegeven(BRawInfo.ERawGegeven.Inschrijver3)))
                aantalInschrijvers++;
            if (!String.IsNullOrEmpty(_Begroting._RawInfo.RawStringGegeven(BRawInfo.ERawGegeven.Inschrijver4)))
                aantalInschrijvers++;
        }
        return aantalInschrijvers;
    }
