    #region methods
    /// <summary>Sommige regels die afgedrukt moeten worden komen overeen met rijen in de begrotingstabel. Bereken hier het overeenkomstige rijnummer.
    /// - Er is geen overeenkomst bij: Eenmalige kosten (code 919990), RawSubTotaal, Begin blanco staartblad
    /// </summary>
    /// <param name="rijNr">Het nummer van de regel in het rapport</param>
    /// <returns>Het nummer van de rij in de begrotingstabel, of -1 indien geen overeenkomst bestaat</returns>
    private int TabelRijNr(int rijNr)
    {
        if (m_SubTotaalRijNr > 0 || m_RawBlancoStaartbladRijNr >= 0 || m_RawEenmaligeKostenRijNr >= 0)
        {
            #region Voorbeeldindeling
            //                              Tbl        Ext
            // Regelsoort                   Rij RijNr  RijNr
            // ============================ ==  =====  ===
            // 1        *                   01  00
            // 11       *                   02  01
            //  110020  #                   03  02
            //   kp1                        04  03
            //          SUBTOTAAL               04     01
            // 9        *                   05  05
            // 91       *                   06  06
            // 910010   #  ...............  07  07
            // 910020   #  ...............  08  08
            // 910030   #  ...............  09  09
            // 910040   #  ...............  10  10
            // 910050   #  ...............  11  11
            // 918880   #  Overige eenmali  12  12
            // 919990      TOTAAL EENM. KST     13     02
            // 929990   #  Uitvoeringskost  13  14
            // 939990   #  Algemene kosten  14  15
            // 949990   #  Winst en risico  15  16
            // 95       *	STELPOSTEN       16  17
            // 951      *  MEERWERK: STELP  17  18
            // 951010	#	Stelpost accept  18  19
            //          Z  Stelpost.        19  20
            // Aanneemsom exclusief BTW     20  21     03
            // Lege regel                   21  22     04
            // Gedaan te                    22  23     05
            // Lege regel                   23  24     06
            // De                           24  25     07
            // Lege regel                   25  26     08
            // De inschrijvers              26  27     09
            // 9        *                       28     10
            // 91       *                   06         11
            // 910010   #  ...............  07         12
            // 910020   #  ...............  08         13
            // 910030   #  ...............  09         14
            // 910040   #  ...............  10         15
            // 910050   #  ...............  11         16
            // 918880   #  Overige eenmali  12         17
            // 919990      TOTAAL EENM. KST            18
            // 929990   #  Uitvoeringskost  13         19
            // 939990   #  Algemene kosten  14         20
            // 949990   #  Winst en risico  15         21
            // 95       *	STELPOSTEN       16         22
            // 951      *  MEERWERK: STELP  17         23
            // 951010	#	Stelpost accept  18         24
            //          Z  Stelpost.        19         25
            // Aanneemsom exclusief BTW     20         26
            // Lege regel                   21         27
            // Gedaan te                    22         28
            // Lege regel                   23         29
            // De                           24         30
            // Lege regel                   25         31
            // De inschrijvers              26         32

            // BepaalAantalStaartregels() = 
            // m_AantalExtraRijen = indien blanco staartblad 2 * m_AantalExtraRijen + aantal staartrijen (2 * dezelfde staart set)
            //                    = c_RawAantalExtraRijen + Eenmalige kosten + Subtotaal = 7 + 1 + 1 = 9
            //                    = met blanco staartblad 2 * m_AantalExtraRijen + BepaalAantalStaartregels() = (2 * 9  ) + 7
            // m_AantalTabelRijen = Het werkelijke aantal regels in de bgrtabel (bgr en rawstaart)
            // AantalRijen()      = m_AantalTabelRijen in de bgrtabel (bgr en rawstaart) + extra rijen (totaal 34) 
            // m_RawBlancoStaartbladRijNr = AantalRijen() inclusief m_AantalExtraRijen (exclusief de blanco staart zelf)

            #endregion Voorbeeldindeling

            // Als de regel in het "blanco" staartblad gedeelte zit dan corrigeren naar "echte" regel
            if (m_RawBlancoStaartbladRijNr >= 0 && rijNr >= m_RawBlancoStaartbladRijNr)
            {
                rijNr -= AantalRijen() - m_RawBlancoStaartbladRijNr;
            }
            int rijNrOrg = rijNr;
            if (m_SubTotaalRijNr > 0)
            {
                if (rijNr <= m_SubTotaalRijNr) // <= ipv < 9 geeft nu weer 9 ipv -1
                {
                    return rijNr;
                }
                if (rijNr > m_SubTotaalRijNr &&
                   rijNr - 1 < m_AantalTabelRijen + (m_RawEenmaligeKostenRijNr != -1 ? 1 : 0))
                {
                    rijNr = rijNr - 1;
                }
            }
            if (m_RawEenmaligeKostenRijNr >= 0)
            {
                if (rijNr < m_RawEenmaligeKostenRijNr && rijNrOrg != m_SubTotaalRijNr)
                {
                    return rijNr;
                }
                if (rijNr > m_RawEenmaligeKostenRijNr && rijNr - 1 < m_AantalTabelRijen)
                {
                    return rijNr - 1;
                }
            }
            else
            {
                if (rijNr < m_AantalTabelRijen)
                {
                    return rijNr;
                }
            }
        }
        else
        {
            if (rijNr < m_AantalTabelRijen)
            {
                return rijNr;
            }
        }
        return -1;
    }

