        {
            geenWaarde = false;

            int tabelRijNr = TabelRijNr(rijNr);
            if (tabelRijNr >= 0)
            {
                if (_RawInschrijfstaat &&                                // Er wordt nu een RAW-inschrijfstaat afgedrukt
                   kolomNr == (int)BBegrotingsRegel.EGegeven.btohvh)     // Hoeveelheidsresultaatverplichting?
                {
                    string postcode = m_BegrotingTabel.VeldString((int)BBegrotingsRegel.EGegeven.cclcde, tabelRijNr);
                    RawJaarversie jaarversie = RawRegelgeving.GetRawJaarversie(_Begroting._RawInfo._Jaarversie);
