        {
            string waarde = m_BegrotingTabel.VeldString(kolomNr, tabelRijNr);
            if ((EGegeven)kolomNr == BBegrotingsRegel.EGegeven.postaard)
            {
                if (GeefOnderbouwingstype(tabelRijNr) == EOnderbouwing.Element &&
                    m_BegrotingTabel.GeefNiveau(tabelRijNr) == 2 &&
                    waarde.Trim() == string.Empty &&
                    m_RawType != RawContractVorm.Raamovereenkomst)
                {
                    return "V";
                }
            }
            return waarde;
        }
        Debug.Assert(_RawInschrijfstaat, "VeldString() - geen tabelRijNr, toch geen RAW-inschrijfstaat");

        if (InBlancoStaartblad(rijNr))
            rijNr -= AantalRijen() - m_RawBlancoStaartbladRijNr;
        if (rijNr == (m_SubTotaalRijNr > 0 ? m_RawEenmaligeKostenRijNr + 1 : m_RawEenmaligeKostenRijNr))
        {
            switch ((EGegeven)kolomNr)
            {
                case BBegrotingsRegel.EGegeven.cclcde: return "919990     N";
                case BBegrotingsRegel.EGegeven.postaard:
                    if (m_RawType == RawContractVorm.Overeenkomst)
                    {
                        return "O";
                    }
                    return "N";
                case BBegrotingsRegel.EGegeven.oms: return "Totaal eenmalige kosten";
                case BBegrotingsRegel.EGegeven.enh: return m_RawEenmaligeKostenEnh;
            }
        }
        if (rijNr == m_SubTotaalRijNr)
        {
            switch ((EGegeven)kolomNr)
            {
                case BBegrotingsRegel.EGegeven.oms: return "SUBTOTAAL";
                case BBegrotingsRegel.EGegeven.enh: return m_RawEenmaligeKostenEnh;
                default: return string.Empty;
            }
        }
        else if (kolomNr == (int)BBegrotingsRegel.EGegeven.oms)
        {
            // Zes extra regels:
            // Aanneemsom exclusief BTW
            // Lege regel
            // Gedaan te
            // Lege regel
            // De
            // Lege regel
            // De inschrijvers
            int extraRijNr = rijNr - RawStaartAanneemsomRijNr();
            Debug.Assert(extraRijNr >= 0 && extraRijNr < c_RawAantalExtraRijen, "VeldString() - verkeerd nummer voor de extra rijen: " + extraRijNr.ToString());
            Debug.Assert(_Begroting._RawInfo != null, "_Begroting._RawInfo == null!!");
            switch (extraRijNr)
            {
                case 0:
                    if (m_RawType == RawContractVorm.Raamovereenkomst)
                        return "INSCHRIJVINGSSOM, EXCLUSIEF BTW";
                    else
                        return "AANNEEMSOM, EXCLUSIEF BTW";
                case 2:
                    string plaats = _Begroting._RawInfo.RawStringGegeven(BRawInfo.ERawGegeven.GedaanTe);
                    return "Gedaan te " + plaats;
                case 4:
                    string datum = _Begroting._RawInfo.RawStringGegeven(BRawInfo.ERawGegeven.GedaanDatum);
                    return "De " + datum;
                case 6:
                    string inschijvers = string.IsNullOrEmpty(_Begroting._RawInfo.RawStringGegeven(BRawInfo.ERawGegeven.Inschrijver1)) ? string.Empty : "\n" + _Begroting._RawInfo.RawStringGegeven(BRawInfo.ERawGegeven.Inschrijver1);
                    inschijvers += string.IsNullOrEmpty(_Begroting._RawInfo.RawStringGegeven(BRawInfo.ERawGegeven.Inschrijver2)) ? string.Empty : "\n" + _Begroting._RawInfo.RawStringGegeven(BRawInfo.ERawGegeven.Inschrijver2);
                    inschijvers += string.IsNullOrEmpty(_Begroting._RawInfo.RawStringGegeven(BRawInfo.ERawGegeven.Inschrijver3)) ? string.Empty : "\n" + _Begroting._RawInfo.RawStringGegeven(BRawInfo.ERawGegeven.Inschrijver3);
                    inschijvers += string.IsNullOrEmpty(_Begroting._RawInfo.RawStringGegeven(BRawInfo.ERawGegeven.Inschrijver4)) ? string.Empty : "\n" + _Begroting._RawInfo.RawStringGegeven(BRawInfo.ERawGegeven.Inschrijver4);
                    return "De inschrijver(s)," + inschijvers;
            }
        }
        return string.Empty;
    }

