    /// <summary>Een regel is een RawBeginStaartRegel als
    /// 1) Het een raw begroting is
    /// 2) Het een type element is
    /// 3) Het een element van 
    /// 3) Het een "9" of een "91" code is 
    /// </summary>
    /// <param name="stuRegel"></param>
    /// <returns></returns>
    public ERawBeginStaart RawIsBeginRawStaart(BStructuurRegel stuRegel)
    {
        ERawBeginStaart type = ERawBeginStaart.Geen;
        if (m_RawBegroting && stuRegel != null && stuRegel._Niveau == 1 && stuRegel._Tpe == EOnderbouwing.Element)
