    private static ERawBijzonderRegelType GeefRawRegelType(string code, RawJaarversie jaarversie)
    {
        ERawBijzonderRegelType tpe = ERawBijzonderRegelType.Geen;
        switch (code)
        {
            case RawRegelgeving.c_RawRawBijdrageCode:
                tpe = ERawBijzonderRegelType.Raw;
                break;
            case RawRegelgeving.c_RawFcoBijdrageCode:
                tpe = ERawBijzonderRegelType.Fco;
                break;
            case RawRegelgeving.c_RawVsiBijdrageCode:
                tpe = ERawBijzonderRegelType.Vsi;
                break;
            case RawRegelgeving.c_RawTotEenmaligeKostenCodeTem2015:
                if (jaarversie <= RawJaarversie.v2015)
                    tpe = ERawBijzonderRegelType.TotEenmaligeKosten;
                break;
            case RawRegelgeving.c_RawUitvoeringsKostenCode:
                tpe = ERawBijzonderRegelType.UitvoeringKosten;
                break;
            case RawRegelgeving.c_RawWRCode:
                tpe = ERawBijzonderRegelType.Winst;
                break;
            case RawRegelgeving.c_RawAKCode:
                tpe = ERawBijzonderRegelType.AK;
                break;
        }
        return tpe;
    }
