    public bool HeeftBrutoVzpInRawStaart(IBegroting begroting, BContext context)
    {
        bool brutoVzpInRawStaart = false;
        _logboek.ContextView = context._View;
        _logboek.Document = context._Document;

        BKostenpost? ktp;
        BStructuurRegel stuRegel;

        for (int stuIndex = begroting._Stu._Aantal - 1; stuIndex > 0; stuIndex--)
        {
            stuRegel = begroting._Stu[stuIndex];
            if (RawIsBeginRawStaart(stuRegel) != ERawBeginStaart.Geen)
            {
                break;
            }
            ktp = stuRegel._Regel as BKostenpost;
            if (ktp != null && ktp._HeeftBrutoVzp)
            {
                _logboek.Toevoegen(begroting._Naam, stuIndex, ProjectResources.TradA0005); // Bruto verzamelpost in de rawstaart
                brutoVzpInRawStaart = true;
            }
        }

        return brutoVzpInRawStaart;
    }
    /// <summary>Een regel is een RawBeginStaartRegel als
    /// 1) Het een raw begroting is
    /// 2) Het een type element is
    /// 3) Het een element van 
    /// 3) Het een "9" of een "91" code is 
    /// </summary>
    /// <param name="stuRegel"></param>
    /// <returns></returns>
    public ERawBeginStaart RawIsBeginRawStaart(BStructuurRegel stuRegel)
    {
        ERawBeginStaart type = ERawBeginStaart.Geen;
        if (m_RawBegroting && stuRegel != null && stuRegel._Niveau == 1 && stuRegel._Tpe == EOnderbouwing.Element)
        {
            switch (stuRegel._Regel._CclCde.Trim())
            {
                case RawRegelgeving.c_RawStaartCode: type = ERawBeginStaart.Code9; break;
                case RawRegelgeving.c_RawStaartCode91: type = ERawBeginStaart.Code91; break;
            }
        }
        return type;
    }

