        public BOpdracht? KopieerBegrotingsRegels(IBegroting bgr, int stuIndexOrig, int aantal, int stuIndexDoel, bool bbdSectie, ref BMeetstaat.EKopieerKoppeling kopieerKoppeling)
        {
            Debug.Assert(m_Stu != null, "BBegroting.KopieerBegrotingsRegels() - geen structuurlijst");
            Debug.Assert(bgr._Stu != null, "BBegroting.KopieerBegrotingsRegels() - geen structuurlijst");
