            Debug.Assert(stuIndexOrig > 0 && stuIndexOrig < bgr._Stu._Aantal, "BBegroting.KopieerBegrotingsRegels() - orig-index verkeerd");
            Debug.Assert(aantal > 0 && stuIndexOrig + aantal <= bgr._Stu._Aantal, "BBegroting.KopieerBegrotingsRegels() - aantal verkeerd");

            if (aantal > 0)
            {
                BSelectie selectie = new BSelectie(stuIndexOrig, stuIndexOrig + aantal);
                KopieerBegrotingRegelsOpdracht opdracht = new KopieerBegrotingRegelsOpdracht(this, bgr, selectie, bbdSectie);
