                    koppeling = _MeetstaatKoppelingen[index];
                    if (koppeling._MeetstaatId == meetstaat._Id &&
                       koppeling._RegelId == meetstaatRegel._Id)
                    {
                        int kolomNr = koppeling._KolomNr;
                        if (kolomNr < 0 || kolomNr >= ak ||
                           kolommen[kolomNr]._Id != koppeling._KolomId)
