        public bool VerwijderMeetstaatKoppeling(int kid, out BMeetstaatKoppeling? mk, out BewaarItemMutatieStatus mut)
        {
            mk = null;
            mut = BewaarItemMutatieStatus.Ongewijzigd;

            if (_MeetstaatKoppelingen._Aantal > 0 && kid != 0)
            {
                if (kid < 0)
                    kid = -kid;

                BMeetstaatKoppeling koppeling;
                for (int index = _MeetstaatKoppelingen._Aantal - 1; index >= 0; index--)
                {
                    koppeling = _MeetstaatKoppelingen[index];
                    if (koppeling._KoppelingId == kid)
                    {
                        mk = koppeling;
                        mut = koppeling._MutatieStatus;
                        mk.ZetMutatieStatus(BewaarItemMutatieStatus.Verwijderd);
