        /// <summary>Zoek een opgegeven elementcode van een gegeven niveau
        /// </summary>
        /// <param name="zoekCode">De gezochte code (gezocht wordt op een trimend code)</param>
        /// <param name="stuIndex">Begin zoeken bij deze index</param>
        /// <param name="vanNiveau">De gevraagde code moet van hetzelfde niveau zijn (of van ??n van de kinderen ?)</param>
        /// <returns>Indien gevonden de index van de sturegel anders -1</returns>
        public int ZoekElementCodeVanNiveau(string zoekCode, int stuIndex, int vanNiveau)
        {
            int gevondenIndex = -1;
            int beginZoeken = 0;
            int eindeZoeken = _Stu._Aantal - 1;

            if (vanNiveau > 1)
            {
                // Zoek binnen element tradEltParentId naar kinderen met dezelfde code
                beginZoeken = stuIndex;
                eindeZoeken = _Stu.EindeElement(stuIndex);
            }

            // Zoek nu in de range stuIndex tm EindeElement
            // naar een elementregel van het gewenste niveau en met de opgegeven zoekcode
            for (int zoekIndex = beginZoeken; zoekIndex < eindeZoeken; zoekIndex++)
            {
                if (_Stu[zoekIndex]._Niveau == vanNiveau && _Stu[zoekIndex]._Tpe == EOnderbouwing.Element)
                {
                    IBegrotingsRegel? elementRegel = _Stu.LeesBegrotingsRegel(zoekIndex)._Regel;
                    string? elementCode = elementRegel?._CclCde.TrimEnd();
                    if (string.Compare(elementCode, zoekCode, true) == 0)
                    {
                        gevondenIndex = zoekIndex;
                        break;
                    }
                }
            }
            return gevondenIndex;
        }

