        /// <summary>
        /// Wijzig de URL's in de begroting
        /// </summary>
        /// <param name="oudeWaarde">Zoektekst of -tekstfragment</param>
        /// <param name="nieuweWaarde">Vervangende tekst</param>
        /// <param name="controleVraag">Vraag de gebruiker om toestemming per vervanging</param>
        /// <returns>Aantal gewijzigde URL's</returns>
        public int WijzigLinks(string oudeWaarde, string nieuweWaarde, WijzigenControlevraagDlgte? controleVraag)
        {
            int gewijzigd = 0;

            string zoekTekst = oudeWaarde.ToLower();
            int aantal = _Stu._Aantal;
            int pos;
            bool stoppen = false;
            string url;
            StringBuilder nieuweUrl = new StringBuilder();
            for (int stuIndex = 1; stuIndex < aantal; stuIndex++)
            {
                BStructuurRegel stuRegel = _Stu[stuIndex];
                if (stuRegel._Tpe == EOnderbouwing.Element && stuRegel._Regel is BElement elt)
                {
                    url = elt._Url ?? string.Empty;
                    if (url.Length != 0)
                    {
                        pos = url.ToLower().IndexOf(zoekTekst);
                        if (pos >= 0)
                        {
                            nieuweUrl = new StringBuilder(nieuweWaarde);
                            if (pos > 0)
                                nieuweUrl = new StringBuilder(url.Substring(0, pos) + nieuweUrl);
                            pos += zoekTekst.Length;
                            if (pos < url.Length)
                                nieuweUrl.Append(url.Substring(pos));
                            if (controleVraag != null && !controleVraag(url, nieuweUrl.ToString(), out stoppen))
                            {
                                if (stoppen)
                                    break;
                                continue;
                            }
                            elt._Url = nieuweUrl.ToString();
                            gewijzigd++;
                        }
                    }
                }
            }
            if (!stoppen)
            {
                foreach (BMiddel middel in _Mid._Lijst)
                {
                    url = middel._Url;
                    if (url.Length != 0)
                    {
                        pos = url.ToLower().IndexOf(zoekTekst);
                        if (pos >= 0)
                        {
                            nieuweUrl = new StringBuilder(nieuweWaarde);
                            if (pos > 0)
                                nieuweUrl = new StringBuilder(url.Substring(0, pos) + nieuweUrl);
                            pos += zoekTekst.Length;
                            if (pos < url.Length)
                                nieuweUrl.Append(url.Substring(pos));
                            if (controleVraag != null && !controleVraag(url, nieuweUrl.ToString(), out stoppen))
                            {
                                if (stoppen)
                                    break;
                                continue;
                            }
                            middel._Url = nieuweUrl.ToString();
                            gewijzigd++;
                        }
                    }
                }
            }
            if (gewijzigd != 0)
                _OpdrachtVzl.Gewijzigd();
            return gewijzigd;
        }
