    /// <summary>
    /// IFCTabel - Indien mogelijk: voeg een rij toe.
    /// </summary>
    /// <param name="rijNr">Invoegen voor deze rij. Voor de eerste rij geldt: rijNr == 0</param>
    /// <param name="ervoor">true: invoegen voor kolom aangeduid door kolomNr, false: invoegen na die kolom</param>
    /// <returns>true indien gelukt</returns>
    public bool RijToevoegen(int rijNr, bool ervoor)
    {
        if (AlleenLezen())
            return false;

        int stuIndex = StuIndex(rijNr);
        bool lRegelBijSoort = _functionsConfiguration.AddNewLineSameKind.Value ?? false;
        BStructuurRegel stuRegel = m_Structuur[stuIndex];

        if (ervoor && stuIndex > 1 && !lRegelBijSoort)  // Bij de eerste regel van de begroting ontstaat er wel een losse kostenpost!
        {
            stuIndex--;
            ervoor = false;
        }

        BOpdracht opdracht = m_Begroting.MaakBegrotingsRegel(stuIndex, ervoor, true, false, m_ToevoegenSpeciaal);
        opdracht.SetView(m_ViewNr);

        if (stuRegel._Tpe == EOnderbouwing.Element)
            m_Structuur.GewijzigdElement(stuRegel._PrtId);

        m_ToevoegenSpeciaal = false;
        return true;
    }

