    public bool Omzetten(int rijNr, EOnderbouwing naarType)
    {
        Debug.Assert(rijNr >= 0 && rijNr < AantalRijen(), "Verkeerd rijnummer");

        if (AlleenLezen())
            return false;

        int stuIndex = StuIndex(rijNr);
        BStructuurRegel stuRegel = m_Structuur[stuIndex];
        BOpdracht? opdracht = m_Begroting.OmzettenBegrotingsRegel(stuIndex, naarType, true); // !m_Filter
        if (opdracht == null)
            return false;  // Omzetting is mislukt of niet toegestaan

        opdracht.SetView(m_ViewNr);
        if (naarType == EOnderbouwing.Element ||
           stuRegel._Tpe == EOnderbouwing.Element)
            m_Structuur.GewijzigdElement(stuRegel._PrtId);
        return true;
    }
