    }

    public string GeefBegrotingsGegeven(string naam)
    {
        // Gebruik hier geen resouce strings. Bij een kopvoet bestand ziet de gebruiker 
        // de variable in de eigen taal maar onder de motorkap is het een nederlandse key

        BGebruikersGegeven? ggv = m_Begroting._Ggv.GeefGebruikersGegeven(naam);
        if (ggv != null)
            return ggv.GeefWaardeToonbaar(m_Begroting._BasisValuta); // voorheen: ggv._Wde;

        if (string.Compare(naam, "naam", StringComparison.OrdinalIgnoreCase) == 0)
            return m_Begroting._Naam;

        if (string.Compare(naam, "valuta", StringComparison.OrdinalIgnoreCase) == 0)
            return m_Begroting._BasisValuta._Aanduiding;

        if (string.Compare(naam, "valuta-omschrijving", StringComparison.OrdinalIgnoreCase) == 0)
            return m_Begroting._BasisValuta._Omschrijving;

        if (string.Compare(naam, "bruto gebouwinhoud", StringComparison.OrdinalIgnoreCase) == 0)
            return m_Begroting._BrutoGebouwInhoud.ToString("N2", _applicatie.NumberFormatInfo);

        if (string.Compare(naam, "bruto vloeroppervlak", StringComparison.OrdinalIgnoreCase) == 0)
            return m_Begroting._BrutoVloerOppervlak.ToString("N2", _applicatie.NumberFormatInfo);

        if (string.Compare(naam, "uurloon", StringComparison.OrdinalIgnoreCase) == 0)
        {
            try  // GeefUurloon() kan - wegens argument false = niet aanmaken - een exception werpen
            {
                BUurloonB ulB = (BUurloonB)m_Begroting.GeefUurloonBVzl().GeefUurloon(string.Empty, false);
                return ulB._Bdr.AlsText(m_Begroting._BasisValuta);
            }
            catch (Exception ex)
            {
                _logger.LogExceptionWithMessage(ex);
                return string.Empty;
            }
        }

        if (string.Compare(naam, "totaal", StringComparison.OrdinalIgnoreCase) == 0)
            return m_Begroting._BgrBto.AlsText(m_Begroting._BasisValuta);

        if (string.Compare(naam, "omschrijving", StringComparison.OrdinalIgnoreCase) == 0)
            return m_Begroting._Oms;

        if (string.Compare(naam, "Uren", StringComparison.OrdinalIgnoreCase) == 0)
            return m_Begroting._TotUur.ToString("N2", _applicatie.NumberFormatInfo);

        if (string.Compare(naam, "totaal MJOB", StringComparison.OrdinalIgnoreCase) == 0)
            return m_Begroting._TotaalMjob.AlsText(m_Begroting._BasisValuta);

        if (string.Compare(naam, "MJOB Periode", StringComparison.OrdinalIgnoreCase) == 0)
            if (m_Begroting._BrinkKostenbestandEigenschappenOnderhoud._Identificatie == "")
            {
                return string.Empty;
            }
            else
            {
                return string.Format("{0} jaar", m_Begroting._BrinkKostenbestandEigenschappenOnderhoud._MJOBPeriode);
            }

        if (string.Compare(naam, "totaal contante waarde", StringComparison.OrdinalIgnoreCase) == 0)
            return m_Begroting._TotaalContanteWaarde.AlsText(m_Begroting._BasisValuta);

        if (string.Compare(naam, "jaar van contante waarde", StringComparison.OrdinalIgnoreCase) == 0)
            if (m_Begroting._BrinkKostenbestandEigenschappenOnderhoud._Identificatie == "")
            {
                return string.Empty;
            }
            else
            {
                return m_Begroting._BrinkKostenbestandEigenschappenOnderhoud._ContanteWaardeJaar.ToString();
            }

        if (string.Compare(naam, "totaal investering", StringComparison.OrdinalIgnoreCase) == 0)
            return m_Begroting._TotaalInvestering.AlsText(m_Begroting._BasisValuta);

        if (string.Compare(naam, "opleverjaar", StringComparison.OrdinalIgnoreCase) == 0)
            if (m_Begroting._BrinkKostenbestandEigenschappenOnderhoud._Identificatie == "")
            {
                return string.Empty;
            }
            else
            {
                return m_Begroting._BrinkKostenbestandEigenschappenOnderhoud._MJOBOpleverJaar.ToString();
            }

        return string.Empty;
    }
    public void TekstSubstitueren(ref string? tekst)
    {
        // 1. Ga op zoek naar [variabele], bijv. [totaal]
        // 2. Vervang [variabele] door de waarde van de variabele, bijv. 23.000
        // 3. Ga op zoek naar de volgende [variabele]
        if (!string.IsNullOrEmpty(tekst)) // Is er wel tekst?
        {
            int openPos = tekst.IndexOf('[');  // Zoek naar het begin van [variabele]
            while (openPos >= 0)  // Zolang er een rechte haak openen is gevonden
            {
                int sluitPos = tekst.IndexOf(']', openPos + 1); // Zoek de bijbehorende rechte haak sluiten
                if (sluitPos < 0)  // Niet gevonden?
                    break; // Niets meer vervangen

                string variabele = tekst.Substring(openPos + 1, sluitPos - openPos - 1);
                string waarde = GeefBegrotingsGegeven(variabele); // Zoek de waarde van de variable op
                if (!string.IsNullOrEmpty(waarde)) // Waarde van de variabele gevonden?
                {
                    if (variabele == variabele.ToLower()) // Kleine letters gewenst?
                        waarde = waarde.ToLower();
                    else if (variabele == variabele.ToUpper()) // Hoofdletters gewenst?
                        waarde = waarde.ToUpper();
                    tekst = tekst.Substring(0, openPos) + waarde + tekst.Substring(sluitPos + 1); // De substitutie zelf
                }
                openPos = tekst.IndexOf('[', openPos + 1);  // Zoek de volgende rechte haak openen
            }
        }
    }

