    /// <summary>
    /// IROTabel - Geef huidige aantal rijen in de tabel
    /// </summary>
    /// <returns>Aantal rijen</returns>
    public int AantalRijen()
    {
        Debug.Assert(m_Structuur._Aantal > 0, "BBegrotingTabel.AantalRijen - begrotingstructuur is leeg");

