    /// <summary>
    /// Geef een korte naam die het soort rij omschrijft, bijv. "definitie", "commentaar"
    /// </summary>
    /// <param name="rijSoort">bijv. stuurkode</param>
    /// <returns>naam van de rijsoort, evt. string.Empty</returns>
    public string RijSoortNaam(char rijSoort)
    {
        string naam;
        switch (rijSoort)
        {
            case 'H': naam = ProjectResources.TradHoofdstuk; break;
            case 'K': naam = ProjectResources.TradKostenpost; break;
            case 'L': naam = ProjectResources.TradLosse_kostenpost; break;
            case 'S': naam = ProjectResources.TradSubhoofdstuk; break;
            case 'E': naam = ProjectResources.TradElement; break;
            case 'P': naam = ProjectResources.TradParagraaf; break;
            case 'O': naam = ProjectResources.TradOpslagpost; break;
            case 'C': naam = ProjectResources.TradCommentaar; break;
            default:
                throw new OnbekendeRijsoortException();  //NIETVERTALEN
        }
        return naam;
    }
