        public void ZetMutatiestatusOngewijzigd()
        {
            if (_Stu != null)
            {
                int aantalRegels = _Stu._Aantal;
                for (int rglNr = 0; rglNr < aantalRegels; rglNr++)
                {
                    BStructuurRegel stuRegel = _Stu[rglNr];
                    if (stuRegel._Regel == null)
                    {
                        continue;
                    }

                    stuRegel._Regel.ZetMutatieStatus(BewaarItemMutatieStatus.Ongewijzigd);
                    stuRegel._Regel._Meting?.ZetMutatieStatus(BewaarItemMutatieStatus.Ongewijzigd);

                }
                UittrekstaatKoppelingen.ZetAlleStatussen(BewaarItemMutatieStatus.Ongewijzigd); //TODO_US: line was in loop above, seems odd, test if this is fine here.
            }

            foreach (BMiddel middel in _Mid._Lijst)
            {
                middel.ZetMutatieStatus(BewaarItemMutatieStatus.Ongewijzigd);
            }

            foreach (BMeetstaat meetstaat in _Meetstaten)
            {
                meetstaat.ZetMutatieStatus(BewaarItemMutatieStatus.Ongewijzigd);
                foreach (BMeetstaatRegel meetstaatRegel in meetstaat._Regels)
                {
                    meetstaatRegel._Meting?.ZetMutatieStatus(BewaarItemMutatieStatus.Ongewijzigd);
                }
            }

            foreach (IMeetstaatModel model in _MeetstaatModelVzl._Modellen)
            {
                model.ZetMutatieStatus(BewaarItemMutatieStatus.Ongewijzigd);
            }

            foreach (BUurloonB uurloonB in GeefUurloonBVzl())
            {
                uurloonB.ZetMutatieStatus(BewaarItemMutatieStatus.Ongewijzigd);
            }

            foreach (BValutaDeco begrotingsValuta in BegrotingsValuta)
            {
                begrotingsValuta.ZetMutatieStatus(BewaarItemMutatieStatus.Ongewijzigd);
            }

            _MeetstaatKoppelingen.MutatiesVerwerkt();

            Documenten.ZetMutatieStatus(BewaarItemMutatieStatus.Ongewijzigd);
        }
