        /// </summary>
        /// <param name="bgr">De begroting waar de originele regels staan (mag ook de huidige begroting zijn)</param>
        /// <param name="stuIndexOrig">De index van het structuurelement behorend bij de eerste originele regel</param>
        /// <param name="aantal">Het aantal regels dat gekopieerd moet worden</param>
        /// <param name="stuIndexDoel">De bestemming in de huidige begroting voor de gekopieerde regels</param>
        public BOpdracht? KopieerBegrotingsRegels(IBegroting bgr, int stuIndexOrig, int aantal, int stuIndexDoel, bool bbdSectie, ref BMeetstaat.EKopieerKoppeling kopieerKoppeling)
        {
            Debug.Assert(m_Stu != null, "BBegroting.KopieerBegrotingsRegels() - geen structuurlijst");
            Debug.Assert(bgr._Stu != null, "BBegroting.KopieerBegrotingsRegels() - geen structuurlijst");
            Debug.Assert(stuIndexDoel > 0 && stuIndexDoel <= _Stu._Aantal, "BBegroting.KopieerBegrotingsRegels() - doel-index verkeerd");
            Debug.Assert(stuIndexOrig > 0 && stuIndexOrig < bgr._Stu._Aantal, "BBegroting.KopieerBegrotingsRegels() - orig-index verkeerd");
            Debug.Assert(aantal > 0 && stuIndexOrig + aantal <= bgr._Stu._Aantal, "BBegroting.KopieerBegrotingsRegels() - aantal verkeerd");

            if (aantal > 0)
            {
                BSelectie selectie = new BSelectie(stuIndexOrig, stuIndexOrig + aantal);
                KopieerBegrotingRegelsOpdracht opdracht = new KopieerBegrotingRegelsOpdracht(this, bgr, selectie, bbdSectie);
                opdracht.StuIndexDoel = stuIndexDoel;
                if (kopieerKoppeling != BMeetstaat.EKopieerKoppeling.Onbekend)
                    opdracht.KopieerKoppeling = kopieerKoppeling;

                if (KopieerBegrotingsRegels(opdracht) != null)
                {
                    if (kopieerKoppeling == BMeetstaat.EKopieerKoppeling.Onbekend &&
                        (opdracht.MeetstaatGevondenKlassiek || opdracht.MeetstaatGevondenBimOnline || opdracht.MeetstaatGevondenIbisMeten))
                        kopieerKoppeling = opdracht.KopieerKoppeling;
                    return opdracht;
                }
            }
            return null;
        }

