        public IEnumerable<IBegrotingsRegel> GeefSelectieBegrotingsRegels(BSelectie selectie)
        {
            selectie.Reset();

            while (selectie.GeefVolgendeRange(out int begin, out int eind))
            {
                for (int rij = begin; rij < eind; rij++)
                {
                    BStructuurRegel stuRegel = _Stu[rij + 1];
                    if (stuRegel._Regel != null)
                        yield return stuRegel._Regel;
                }
            }
        }
