            bool[] kolomGekoppeld = new bool[ak];
            if (_MeetstaatKoppelingen._Aantal > 0 && meetstaatRegel._Id != 0)
            {
                BMeetstaatKoppeling koppeling;
                for (int index = _MeetstaatKoppelingen._Aantal - 1; index >= 0; index--)
                {
                    koppeling = _MeetstaatKoppelingen[index];
                    if (koppeling._MeetstaatId == meetstaat._Id &&
                       koppeling._RegelId == meetstaatRegel._Id)
                    {
                        int kolomNr = koppeling._KolomNr;
                        if (kolomNr < 0 || kolomNr >= ak ||
                           kolommen[kolomNr]._Id != koppeling._KolomId)
                        {
                            kolomNr = meetstaat._Model?.GeefKolomNr(koppeling._KolomId) ?? -1;
                            if (kolomNr >= 0)
                                koppeling._KolomNr = kolomNr;
                        }
                        if (kolomNr >= 0)
                        {
                            kolomGekoppeld[kolomNr] = true;
                        }
                    }
                }
            }
            return kolomGekoppeld;
