        public bool HeeftKoppelingen(IMeetstaat meetstaat)
        {

            if (_MeetstaatKoppelingen._Aantal > 0)
            {
                //De koppeling kan afkomstig zijn uit de begroting of het begrotingsBlad
                BMeetstaatKoppeling koppeling;

                for (int index = _MeetstaatKoppelingen._Aantal - 1; index >= 0; index--)
                {
                    koppeling = _MeetstaatKoppelingen[index];
                    if (koppeling._MeetstaatId == meetstaat._Id)
                    {
                        if (0 == koppeling._DocumentId)  // Afkomstig uit begrotingsblad
                        {
                            if (0 == _Bbd._Tabel._Lijst.Count)  // Lees de begrotingstabelgegevens, en reken
                            {
                                BegrotingBladRekenen();
                            }
                            foreach (BBgrBladRegel item in _Bbd._Tabel._Lijst)
                            {
                                if (null != item._Functie &&
                                    Math.Abs(item._Functie._MstKid) == Math.Abs(koppeling._KoppelingId))  // Als de koppelingsid gelijk is
                                {
                                    return true;
                                }
                            }
                        }
                        else //  Afkomstig uit begroting
                        {
                            if (HeeftGekoppeldeBegrotingsRegel(koppeling))
                                return true;
                        }
                    }
                }
            }
            return false;
        }
        public int GeefAantalKoppelingen(IMeetstaat meetstaat, out int aantalOverschreven)
        {
            int aantal = 0;
            aantalOverschreven = 0;

            if (_MeetstaatKoppelingen._Aantal > 0)
            {
                //De koppeling kan afkomstig zijn uit de begroting of het begrotingsBlad
                IBegrotingsRegel? bgrRegel;
                BMeetstaatKoppeling koppeling;
                for (int index = _MeetstaatKoppelingen._Aantal - 1; index >= 0; index--)
                {
                    koppeling = _MeetstaatKoppelingen[index];
                    if (koppeling._MeetstaatId == meetstaat._Id)
                    {
                        if (0 == koppeling._DocumentId)//afkomstig uit begrotingsblad
                        {
                            if (0 == _Bbd._Tabel._Lijst.Count)//lees de begrotingstabel gegevens, en reken
                            {
                                BegrotingBladRekenen();
                            }
                            foreach (BBgrBladRegel item in _Bbd._Tabel._Lijst)
                            {
                                if (null != item._Functie)
                                {
                                    if (Math.Abs(item._Functie._MstKid) == Math.Abs(koppeling._KoppelingId))//als de koppelingsid gelijk is
                                    {
                                        aantal++;
                                        Debug.Assert(item._Functie._KoppelingStatus != EKoppelingStatus.Geen, "BBegroting.GeefAantalKoppelingen() - geen koppeling");

                                        if (item._Functie._KoppelingStatus == EKoppelingStatus.Geen)
                                            aantal = 0;

                                        if (item._Functie._KoppelingStatus == EKoppelingStatus.Overschreven)
                                            aantalOverschreven++;
                                    }
                                    //break;
                                }
                            }
                        }
                        else //afkomstig uit begroting
                        {
                            bgrRegel = ZoekGekoppeldeBegrotingsRegel(koppeling);
                            if (bgrRegel != null)
                            {
                                aantal++;

                                Debug.Assert(bgrRegel._KoppelingStatus != EKoppelingStatus.Geen, "BBegroting.GeefAantalKoppelingen() - geen koppeling");

                                if (bgrRegel._KoppelingStatus == EKoppelingStatus.Geen)
                                    aantal = 0;

                                if (bgrRegel._KoppelingStatus == EKoppelingStatus.Overschreven)
                                    aantalOverschreven++;
                            }
                        }
                    }
                }
            }
            return aantal;
        }

        public void HoeveelhedenOvernemen(IMeetstaat meetstaat)
        {
            if (meetstaat == null || _MeetstaatKoppelingen._Aantal == 0)
                return;

            BMeetstaatKoppeling koppeling;
            bool wijziging = false;

            for (int index = _MeetstaatKoppelingen._Aantal - 1; index >= 0; index--)
            {
                koppeling = _MeetstaatKoppelingen[index];
                if (koppeling._MeetstaatId != meetstaat._Id)
                    continue;

                double hvh = meetstaat.GeefGekoppeldeWaarde(koppeling, out bool geenWaarde);
                if (geenWaarde)
                    continue;

                if (koppeling._DocumentId != 0)
                {
                    if (HoeveelhedenOvernemenBgr(meetstaat, koppeling, hvh))
                        wijziging = true;

                    if (_BrinkKostenbestandEigenschappenOnderhoud?._MJOBActiefBerekenen != true)
                    {
                        _MjobContanteWaardeIsActueel = false;
                    }
                }
                else
                {
                    // Het is geen begrotingsregel: is het een begrotingblad of algemene gegevens koppeling
                    if (HoeveelhedenOvernemenAlg(meetstaat, koppeling, hvh))
                        wijziging = true;

                    if (HoeveelhedenOvernemenBbd(meetstaat, koppeling, hvh))
                        wijziging = true;
                }
            }

            if (wijziging)
            {
                _OpdrachtVzl.Gewijzigd();
            }
        }

        private bool HoeveelhedenOvernemenBgr(IMeetstaat meetstaat, BMeetstaatKoppeling koppeling, double hvh)
        {
            IBegrotingsRegel? bgrRegel = ZoekGekoppeldeBegrotingsRegel(koppeling);
            if (bgrRegel == null)
                return false;

            Debug.Assert(bgrRegel._KoppelingStatus != EKoppelingStatus.Geen, "BBegroting.HoeveelhedenOvernemen() - geen koppeling");
            if (bgrRegel._KoppelingStatus != EKoppelingStatus.Gekoppeld)
                return false;

            return bgrRegel.MeetstaatHoeveelheid(hvh);
        }

        private bool HoeveelhedenOvernemenBbd(IMeetstaat meetstaat, BMeetstaatKoppeling koppeling, double hvh)
        {
            return m_Bbd?.HoeveelhedenOvernemen(meetstaat, koppeling, hvh) ?? false;
        }

        private bool HoeveelhedenOvernemenAlg(IMeetstaat meetstaat, BMeetstaatKoppeling koppeling, double hvh)
        {
            bool wijziging = false;
            foreach (BGebruikersGegeven ggv in m_Ggv ?? Enumerable.Empty<BGebruikersGegeven>())
            {
                if (ggv._Mstkid == koppeling._KoppelingId)
                {
                    if (ggv.WijzigDouble(hvh))
                        wijziging = true;
                }
            }
            return wijziging;
        }

