                for (int index = _MeetstaatKoppelingen._Aantal - 1; index >= 0; index--)
                {
                    koppeling = _MeetstaatKoppelingen[index];
                    if (koppeling._KoppelingId == kid)
                    {
                        mk = koppeling;
                        mut = koppeling._MutatieStatus;
                        mk.ZetMutatieStatus(BewaarItemMutatieStatus.Verwijderd);
                        _MeetstaatKoppelingen.Verwijderen(index);
                        return true;
                    }
                }
            }
            return false;
        }
        private void VerwijderMeetstaat(int meetstaatId)
        {
            // Geen controles, er wordt geen opdracht gegenereerd
            IMeetstaat meetstaat;
            for (int index = _Meetstaten.Count - 1; index >= 0; index--)
            {
                meetstaat = _Meetstaten[index];
                if (meetstaat._Id == meetstaatId)
                {
                    _Meetstaten.RemoveAt(index);
                    _Metingen?.VerwijderMeetstaatMetingKoppelingen(meetstaatId);
                    break;
                }
            }
        }
        private void GewijzigdModelKoppelingen(BMeetstaat meetstaat)
        {
            if (_MeetstaatKoppelingen._Aantal > 0)
            {
                IMeetstaatModel? model = meetstaat._Model;

                for (int kIndex = _MeetstaatKoppelingen._Aantal - 1; kIndex >= 0; kIndex--)
                {
                    BMeetstaatKoppeling koppeling = _MeetstaatKoppelingen[kIndex];
                    if (koppeling._MeetstaatId == meetstaat._Id)
                    {
                        if (null == model?.GeefKolom(koppeling._KolomId))   // Gekoppelde kolom is verwijderd?
                        {
                            IBegrotingsRegel? bgrRegel = ZoekGekoppeldeBegrotingsRegel(koppeling);
                            if (bgrRegel != null)
                            {
                                bgrRegel.MeetstaatKoppeling(null);
                                _logboek.Toevoegen(
                                   _DocumentNaam,
                                   koppeling._DocumentNr,
                                   $"{ProjectResources.TradC19}{BStatics.c_Spatie}{bgrRegel._Aanduiding}{BStatics.c_Spatie}{ProjectResources.TradC110}");
                            }
                            _MeetstaatKoppelingen.Verwijderen(kIndex);
                        }
                    }
                }
            }
        }
        internal bool HeeftGekoppeldeBegrotingsRegel(BMeetstaatKoppeling koppeling)
        {
            int stuIndex = koppeling._DocumentNr;
            if (stuIndex >= 0 &&
               stuIndex < _Stu._Aantal &&
               _Stu[stuIndex]._Id == koppeling._DocumentId)
            {
                return true;
            }

            if (_Stu.ZoekId(koppeling._DocumentId, out stuIndex))
            {
                return true;
            }

            return false;
        }
        public IBegrotingsRegel? ZoekGekoppeldeBegrotingsRegel(BMeetstaatKoppeling koppeling)
        {
            bool gevonden = false;
            int stuIndex = koppeling._DocumentNr;
            if (stuIndex >= 0 &&
               stuIndex < _Stu._Aantal &&
               _Stu[stuIndex]._Id == koppeling._DocumentId)
            {
                gevonden = true;
            }
            else if (_Stu.ZoekId(koppeling._DocumentId, out stuIndex))
            {
                koppeling._DocumentNr = stuIndex;
                gevonden = true;
            }
            if (gevonden)
            {
                _Stu.LeesBegrotingsRegel(stuIndex);
                return _Stu[stuIndex]._Regel;
            }
            return null;
        }
        internal BBgrBladRegel? ZoekGekoppeldeBegrotingsbladRegel(BMeetstaatKoppeling koppeling)
        {
            BBgrBladRegel? gevondenBbdRegel = null;
            // 
            if (_Bbd._Tabel._Lijst.Count == 0) // lees de begrotingstabel gegevens, en reken
            {
                BegrotingBladRekenen();
            }

            foreach (BBgrBladRegel bbdRegel in m_Bbd?._Tabel?._Lijst ?? Enumerable.Empty<BBgrBladRegel>())
            {
                if (bbdRegel._RegelSoort == BBgrBladRegel.EBbdRegelSoort.Functie)
                {
                    if (bbdRegel._Functie?._FunctieSoort == BBegrotingBladFunctie.EFunctieSoort.Eenheidsprijs)
                    {
                        if (bbdRegel._Functie._MstKid == koppeling._KoppelingId)
                        {
                            gevondenBbdRegel = bbdRegel;
                            break;
                        }
                    }
                }
            }

            return gevondenBbdRegel;
        }
        private void MeetstatenControleren()
        {
            foreach (BMeetstaat meetstaat in _Meetstaten)
            {
                string resultaat = LeesMeetstaat(meetstaat);
                if (!string.IsNullOrEmpty(resultaat))
                {
                    _logboek.Toevoegen(_Naam, resultaat);
                }
                if (GeefAantalKoppelingen(meetstaat) > 0)
                {
                    // Alleen voorlopige invulling melden als de meetstaat daadwerkelijk gebruikt wordt (zie #14352)
                    int ar = meetstaat.AantalRijen();
                    for (int regelNr = 0; regelNr < ar; regelNr++)
                    {
                        if (meetstaat.VeldString(BMeetstaatKolom.c_StuurcodeKolomNr, regelNr) == BMeetstaat.c_StkVoorlopig)
                        {
                            _logboek.Toevoegen(
                               _DocumentNaam,
                               regelNr + 1,
                               meetstaat._Id,
                               $"{ProjectResources.TradC111}{BStatics.c_Spatie}{meetstaat._Omschrijving}",
                               EViewKey.MeetGridInKlassiekView);
                            _logboek.ExtraContextLetter = BMeetstaat.c_ContextLetter;
                        }
                    }
                }
            }
        }
        public void KoppelingKopieren(
           IBegrotingsRegel origRegel,
           IBegrotingsRegel doelRegel,
           BMeetstaat.EKopieerKoppeling kopieerKoppeling,
           BMeetstaatKopieRegistratie meetstaatKopieRegistratie)
        {
            bool binnenBegroting = origRegel.Begroting == doelRegel.Begroting;
            switch (kopieerKoppeling)
            {
                case BMeetstaat.EKopieerKoppeling.Niets:
                    return;

                case BMeetstaat.EKopieerKoppeling.Koppeling:
                    {
                        Debug.Assert(binnenBegroting, "BBegroting.KoppelingKopieren() - verkeerde kopieeroptie bij kopi?ren naar andere begroting");

                        int mstKidOrig = origRegel._MstKid;
                        BMeetstaatKoppeling? koppelingOrig = ZoekMeetstaatKoppeling(mstKidOrig);
                        if (koppelingOrig != null)
                        {
                            var koppelingDoel = new BMeetstaatKoppeling(BewaarItemMutatieStatus.Nieuw, koppelingOrig, doelRegel._Id);
                            koppelingDoel._KoppelingId = GeefNieuwId();
                            if (doelRegel.MeetstaatKoppeling(koppelingDoel))
                            {
                                _MeetstaatKoppelingen.Toevoegen(koppelingDoel);
                                if (origRegel._KoppelingStatus == EKoppelingStatus.Overschreven)
                                    doelRegel.MeetstaatOverschreven(false);
                                meetstaatKopieRegistratie.KoppelingGekopieerd(koppelingDoel._KoppelingId);   // Tbv UNDO
                            }
                        }
                        break;
                    }

                case BMeetstaat.EKopieerKoppeling.Overschreven:
                case BMeetstaat.EKopieerKoppeling.Meetstaat:
                    {
                        int mstKidOrig = origRegel._MstKid;

                        IBegroting? bgrOrig = binnenBegroting ? this : origRegel.Begroting.GeefAndereBegroting(this);
                        if (bgrOrig != null)
                        {
                            BMeetstaatKoppeling? koppelingOrig = bgrOrig.ZoekMeetstaatKoppeling(mstKidOrig);
                            if (koppelingOrig != null)
                            {
                                int meetstaatIdKopie = meetstaatKopieRegistratie.GeefMeetstaatIdKopie(koppelingOrig._MeetstaatId);
                                if (meetstaatIdKopie <= 0)
                                {
                                    BMeetstaat? meetstaatOrig = bgrOrig.GeefMeetstaat(koppelingOrig._MeetstaatId);
                                    BMeetstaat meetstaatKopie;
                                    if (binnenBegroting)
                                    {
                                        meetstaatKopie = new BMeetstaat(meetstaatOrig!, false);
                                    }
                                    else
                                    {
                                        IMeetstaatModel model = ZoekMeetstaatModel(meetstaatOrig!._Model!, meetstaatKopieRegistratie);
                                        Debug.Assert(model != null, "BBegroting.KoppelingKopieren() na ZoekMeetstaatModel() geen model");
                                        meetstaatKopie = new BMeetstaat(meetstaatOrig, model, false);
                                    }
                                    meetstaatIdKopie = meetstaatKopie._Id = GeefNieuwId();
                                    meetstaatKopie.Begroting = this;
                                    _Meetstaten.Add(meetstaatKopie);
                                    meetstaatKopieRegistratie.MeetstaatGekopieerd(meetstaatOrig!._Id, meetstaatIdKopie);
                                }

                                BMeetstaatKoppeling koppelingDoel = new BMeetstaatKoppeling(BewaarItemMutatieStatus.Nieuw, meetstaatIdKopie, koppelingOrig._KolomId, koppelingOrig._RegelId);
                                koppelingDoel._DocumentId = doelRegel._Id;
                                koppelingDoel._KoppelingId = GeefNieuwId();

                                if (doelRegel.MeetstaatKoppeling(koppelingDoel))
                                {
                                    _MeetstaatKoppelingen.Toevoegen(koppelingDoel);
                                    meetstaatKopieRegistratie.KoppelingGekopieerd(koppelingDoel._KoppelingId);   // Tbv UNDO

                                    if (kopieerKoppeling == BMeetstaat.EKopieerKoppeling.Overschreven ||
                                       origRegel._KoppelingStatus == EKoppelingStatus.Overschreven)
                                        doelRegel.MeetstaatOverschreven(false);
                                }
                            }
                        }
                        break;
                    }
                default:
                    return;
            }
            VerhoogMeetstaatVersie();
        }
        public void KoppelingKopieren(IList<BClipboardStructuurRegel> csRegels, BClipboardStructuurRegel csRegel, IBegrotingsRegel doelRegel, BMeetstaat.EKopieerKoppeling kopieerKoppeling,
           BMeetstaatKopieRegistratie meetstaatKopieRegistratie, bool inclusiefMetingen)
        {
            switch (kopieerKoppeling)
            {
                case BMeetstaat.EKopieerKoppeling.Niets:
                    return;

                case BMeetstaat.EKopieerKoppeling.Koppeling:
                    {
                        BMeetstaatKoppeling koppelingOrig = csRegel._MeetstaatKoppeling;
                        if (koppelingOrig != null)
                        {
                            BMeetstaat? meetstaat = GeefMeetstaat(koppelingOrig._MeetstaatId);
                            if (meetstaat == null)
                                goto case BMeetstaat.EKopieerKoppeling.Meetstaat;

                            BMeetstaatKoppeling koppelingDoel = new BMeetstaatKoppeling(BewaarItemMutatieStatus.Nieuw, koppelingOrig, doelRegel._Id);
                            koppelingDoel._KoppelingId = GeefNieuwId();
                            if (doelRegel.MeetstaatKoppeling(koppelingDoel))
                            {
                                _MeetstaatKoppelingen.Toevoegen(koppelingDoel);
                                if (csRegel._KoppelingStatus == EKoppelingStatus.Overschreven)
                                    doelRegel.MeetstaatOverschreven(false);
                                meetstaatKopieRegistratie.KoppelingGekopieerd(koppelingDoel._KoppelingId);   // Tbv UNDO
                            }
                        }
                        break;
                    }

                case BMeetstaat.EKopieerKoppeling.Overschreven:
                case BMeetstaat.EKopieerKoppeling.Meetstaat:
                    {
                        BMeetstaatKoppeling koppelingOrig = csRegel._MeetstaatKoppeling;
                        if (koppelingOrig != null)
                        {
                            // Is de meetstaat al eerder gekopieerd?
                            int meetstaatIdKopie = meetstaatKopieRegistratie.GeefMeetstaatIdKopie(koppelingOrig._MeetstaatId);
                            if (meetstaatIdKopie <= 0)
                            {
                                // Zoek de originele meetstaat
                                BMeetstaat? meetstaatOrig = null;
                                foreach (BClipboardStructuurRegel csr in csRegels)
                                {
                                    if (csr._MeetstaatId == koppelingOrig._MeetstaatId)
                                    {
                                        meetstaatOrig = csr._Meetstaat;
                                        break;
                                    }
                                }
                                Debug.Assert(meetstaatOrig != null, "BBegroting.KoppelingKopieren() - geen meetstaatOrig");
                                if (meetstaatOrig == null)
                                    return;   // niets gekopieerd

                                // Is het model al eerder gekopieerd?
                                IMeetstaatModel meetstaatModel = ZoekMeetstaatModel(meetstaatOrig!._Model!, meetstaatKopieRegistratie);
                                BMeetstaat meetstaatKopie = new BMeetstaat(meetstaatOrig, meetstaatModel, inclusiefMetingen);
                                meetstaatIdKopie = meetstaatKopie._Id = GeefNieuwId();
                                if (inclusiefMetingen && _Metingen != null)
                                    _Metingen.KopieerMetingKoppeling(meetstaatOrig._Id, meetstaatIdKopie);
                                meetstaatKopie.Begroting = this;
                                _Meetstaten.Add(meetstaatKopie);
                                meetstaatKopieRegistratie.MeetstaatGekopieerd(meetstaatOrig._Id, meetstaatIdKopie);
                            }

                            BMeetstaatKoppeling koppelingDoel = new BMeetstaatKoppeling(BewaarItemMutatieStatus.Nieuw, meetstaatIdKopie, koppelingOrig._KolomId, koppelingOrig._RegelId);
                            koppelingDoel._DocumentId = doelRegel._Id;
                            koppelingDoel._KoppelingId = GeefNieuwId();

                            doelRegel.MeetstaatKoppeling(koppelingDoel);
                            _MeetstaatKoppelingen.Toevoegen(koppelingDoel);
                            if (kopieerKoppeling == BMeetstaat.EKopieerKoppeling.Overschreven ||
                               csRegel._KoppelingStatus == EKoppelingStatus.Overschreven)
                                doelRegel.MeetstaatOverschreven(false);
                            // Ook hier moet he juist geregistreerd worden omdat anders de Undo/Redo niet goed gaat
                            meetstaatKopieRegistratie.KoppelingGekopieerd(koppelingDoel._KoppelingId);   // Tbv UNDO
                        }
                        break;
                    }
                default:
                    return;
            }
            VerhoogMeetstaatVersie();
        }
        /// <summary>
        /// Verander de omschrijving van de meetstaat in die van de (eerste) gekoppelde begrotingsregel
        /// </summary>
        /// <param name="meetstaat">De meetstaat waarvan de omschrijving moet worden veranderd</param>
        /// <param name="bgrRegelId">ID van de begrotingsregel die aan de meetstaat is gekoppeld</param>
        /// <returns>true indien gelukt</returns>
        public bool MeetstaatOmschrijving(IMeetstaat meetstaat, int bgrRegelId)
        {
            if (bgrRegelId > 0 &&
               _Stu.ZoekId(bgrRegelId, out int stuIndex) &&
               MeetstaatOmschrijving(stuIndex, meetstaat))
            {
                return true;
            }
            return MeetstaatOmschrijving(meetstaat);
        }
        /// <summary>
        /// Verander de omschrijving van de meetstaat in die van de eerste gekoppelde begrotingsregel
        /// </summary>
        /// <param name="meetstaat">De meetstaat waarvan de omschrijving moet worden veranderd</param>
        /// <returns>true indien gelukt</returns>
        public bool MeetstaatOmschrijving(IMeetstaat meetstaat)
        {
            for (int stuIndex = 1; stuIndex < _Stu._Aantal; stuIndex++)
            {
                if (MeetstaatOmschrijving(stuIndex, meetstaat))
                    return true;
            }
            return false;
        }
        private bool MeetstaatOmschrijving(int stuIndex, IMeetstaat meetstaat)
        {
            _Stu.LeesBegrotingsRegel(stuIndex);
            IBegrotingsRegel? bgrRegel = _Stu[stuIndex]._Regel;
            BMeetstaatKoppeling? koppeling = ZoekMeetstaatKoppeling(bgrRegel?._MstKid ?? 0);
            if (koppeling != null && koppeling._MeetstaatId == meetstaat._Id)
            {
                var hernoemenOpdracht = new MeetstaatHernoemenOpdracht(meetstaat, bgrRegel?._Omschrijving ?? string.Empty);      // Probeer de omschrijving van de meetstaat te wijzigen
                if (OpdrachtUitvoeren(hernoemenOpdracht))
                    VerhoogMeetstaatVersie();
                return true;   // Ook als de opdracht niet kon worden uitgevoerd, misschien is de omschrijving al gelijk aan die van de eerste gekoppelde begrotingsregel
            }
            return false;
        }
        private IMeetstaatModel ZoekMeetstaatModel(IMeetstaatModel externModel, BMeetstaatKopieRegistratie meetstaatKopieRegistratie)
        {
            // Is het model al eerder gevonden?
            int modelId = meetstaatKopieRegistratie.GeefMeetstaatModelIdKopie(externModel._ModelId);
            if (modelId > 0)
            {
                foreach (IMeetstaatModel vzlModel in _MeetstaatModelVzl._Modellen)
                {
                    if (vzlModel._ModelId == modelId)
                        return vzlModel;
                }
            }

            // Is er een model met dezelfde naam?
            BMeetstaatModel? gelijknamigModel = _MeetstaatModelVzl.ZoekModel(externModel._Naam);
            if (gelijknamigModel != null && gelijknamigModel.Vergelijk(externModel))
            {
                meetstaatKopieRegistratie.MeetstaatModelGevonden(modelId, gelijknamigModel._ModelId);
                return gelijknamigModel;
            }

            // Is er een model met dezelfde definitie?
            foreach (IMeetstaatModel vzlModel in m_MeetstaatModelVzl?._Modellen ?? Enumerable.Empty<IMeetstaatModel>())
            {
                if (gelijknamigModel != vzlModel && vzlModel.Vergelijk(externModel))
                {
                    meetstaatKopieRegistratie.MeetstaatModelGevonden(modelId, vzlModel._ModelId);
                    return vzlModel;
                }
            }
            IMeetstaatModel importModel = _MeetstaatModelVzl.ImporteerMeetstaatModel(externModel, gelijknamigModel != null);
            importModel.GeldigModel();  // zorgt voor wat initialisatie

            meetstaatKopieRegistratie.MeetstaatModelGekopieerd(externModel._ModelId, importModel._ModelId);
            return importModel;
        }
