        public void MaakBrutoBegroting(BgrOpslaan bgrOpslaan, bool alleBtwRegels)
        {
            Debug.Assert(m_Bbd != null, "BBegroting.MaakBrutoBegroting() - Er is nog geen begrotingsblad in het BBegroting-object");
            Rekenen(ERekendiepte.Volledig);
            double totaalBegroting = _BgrBto.Waarde;
            IBegroting ibrutobegroting = _maakBrutobegroting.MaakBrutoBegroting(bgrOpslaan, alleBtwRegels, this);
            // Zorg ervoor dat de opdrachten verzameling leeg is na het omzetten naar bruto begroting
            ibrutobegroting.OpdrachtenVergeten();

            _OpdrachtVzl.Gewijzigd();
            ThrowExceptionAlsTotaalOorspronkelijkeBegrotingEnBrutobegrotingVerschilt(totaalBegroting, ibrutobegroting);
        }

        private static void ThrowExceptionAlsTotaalOorspronkelijkeBegrotingEnBrutobegrotingVerschilt(double totaalBegroting, IBegroting ibrutobegroting)
        {
            const double toegestaanVerschilBegrotingsposten = 1d;  // Er mag een klein verschil zijn tussen de oorspronkelijke begroting en de brutobegroting, vanwege afrondingen
            const double toegestaanVerschil = 10d;   // Groter verschil wordt toegelaten

            double totaalBrutoBegroting = ibrutobegroting._BgrBto.Waarde;
            double absVerschil = Math.Abs(totaalBrutoBegroting - totaalBegroting);
            double margeAfrondingsVerschil = ibrutobegroting.BegrotingspostenToepassen ? toegestaanVerschilBegrotingsposten : toegestaanVerschil;
            if (absVerschil >= margeAfrondingsVerschil)
            {
                throw new TotaalOorspronkelijkeBegrotingEnBrutobegrotingVerschiltException();
            }
        }

        public void Rekenen(ERekendiepte diepte)
        {
            Rekenen(diepte, new BBerekenStaart());
        }
        public void BerekenStaart(int bgrPostId)
        {
            _REl._MoetRekenen = true;
            Rekenen(ERekendiepte.Wijzigingen, new BBerekenStaart() { _AlleenStaart = true, _AlleenBgrpostId = bgrPostId });
        }
        private void Rekenen(ERekendiepte diepte, BBerekenStaart berekenStaart)
        {
            _Bbd._BgrPostToepassen = BegrotingspostenToepassen;
            if (m_Snel || m_GroepeerOpdrachten ||
                !MoetRekenen && !_REl._MoetRekenen && diepte == ERekendiepte.Wijzigingen)
                return;

            if (!berekenStaart._GeenVastTotaalBerekenen)
            {
                // Tbv toerekenen naar vast totaal het BVastTotaal-object resetten:
                _VastTotaal.Reset();
            }

            bool meldingen = diepte == ERekendiepte.Meldingen;

            Debug.Assert(_Stu._Aantal > 0 && _Stu[0]._Regel != null, "BBegroting.Rekenen() - Geen rootelement aanwezig in begrotingsstructuur");
            BElement? rootEl = _REl;
            Debug.Assert(m_Bbd != null, "BBegroting.Rekenen() - Er is nog geen begrotingsblad in het BBegroting-object");

            BXtoKst subtotaal = new BXtoKst(_VltId, BegrotingsValuta);
            BRawInfo? rawInfo = (m_Tpe == EBgrTpe.Raw) ? m_RawInfo : null;
            var rekenGegevens = new BRekenGegevens(
                m_Stu,
                diepte,
                m_Tpe,
                _AfgerondRekenen,
                _ElementenOp0,
                rawInfo,
                subtotaal)
            {
                _BerekenStaart = berekenStaart
            };

            do
            {
                _UurloonMeldingen = true;
                RekenMeldingen.LeesRekenMeldingen();

                // Reken in het begrotingblad de begroting door
                m_Bbd.Rekenen(_DocumentNaam, rekenGegevens, rootEl, m_XtoKst, out m_TotUur);  // m_XtoKst en m_TotUur bevatten het resultaat
                diepte = ERekendiepte.Wijzigingen;
                _logboek.GeenDoubluresToevoegen = true;
            } while (m_VastTotaal?.VerderRekenen() == true && berekenStaart?._GeenVastTotaalBerekenen != true);
            _logboek.GeenDoubluresToevoegen = false;

            if (meldingen)
            {
                MeetstatenControleren();
                if (m_BasisValuta!._Onbekend) // Dit is een DocValuta
                    _logboek.Toevoegen(_DocumentNaam, ProjectResources.TradC112, EViewKey.AlgmCtrlInAlgemeenView);
                if (m_AfgerondRekenen?._Afronden == true)
                    _logboek.Toevoegen(_DocumentNaam, ProjectResources.TradC113, EViewKey.AlgmCtrlInAlgemeenView);
                if (ControleerOpVastPrijsIndicatie())
                    _logboek.Toevoegen(_DocumentNaam, ProjectResources.TradC114, EViewKey.BegrGridInKlassiekeView);
                _VastTotaal.Meldingen();
            }

            // Bereken de staartkosten
            //
            //   BgrXtoStr == BgrXto - BgrXtoSks
            //   BgrXto    == _XtoKst[Bto,Aks]
            //   BgrXtoSks == _XtoKst[Bto,Arb] + _XtoKst[Bto,Mta] + _XtoKst[Bto,Mte] + _XtoKst[Bto,Oda]
            //

            if (m_RawInfo != null && m_RawInfo._RawBegroting)
            {
                BBedrag bedrag = new BBedrag(m_VttId, m_RawInfo._RawSubtotaal);
                m_RawInfo.ZetRawSubTotaal(bedrag, BegrotingsValuta);

                bedrag = new BBedrag(m_VttId, m_RawInfo._RawAltSubtotaal);
                m_RawInfo.ZetRawAltSubTotaal(bedrag, BegrotingsValuta);
            }

            _XtoKst[EXto.Bto, EKst.Str] = _XtoKst[EXto.Bto, EKst.Aks] - _XtoKst.GeefSks(EXto.Bto);   // SKS: Arb+Mta+Mte+Oda, geen Str
            _XtoKst[EXto.Nto, EKst.Str] = _XtoKst[EXto.Nto, EKst.Aks] - _XtoKst.GeefSks(EXto.Nto);

            BegrotingBerekendHandler?.BegrotingBerekend();

            rootEl.IsGewijzigd();         // Tbv opslag
            _REl._MoetRekenen = MoetRekenen = false;
            rootEl._TotUur = m_TotUur;
        }

