        public DataTable? HaalAlleOnderhoudsGegevensUitDeCloud(Guid? kostenbestandId)
        {
            DataTable? onderhoudsGegevens = null;
            if (kostenbestandId != null)
            {
                #region Inloggen / Test module / Vaststellen (onderhouds)codes
                if (!KostenbestandInloggen())
                    return null;

                #endregion Inloggen / Test module / Vaststellen (onderhouds)codes

                IBegrotingsRegel begrotingsRegel;
                string onderhoudsCode;
                var regels = new List<BStructuurRegel>();
                foreach (BStructuurRegel regel in _Stu.Lijst)
                {
                    begrotingsRegel = _Stu.GeefBegrotingsRegel(regel);
                    onderhoudsCode = begrotingsRegel.GeefString(BBegrotingsRegel.EGegeven.OnderhoudsCode, false);
                    if (!string.IsNullOrEmpty(onderhoudsCode))
                    {
                        regels.Add(regel);
                    }
                }

                string xmlText = GenereerXmlTekst(regels, BBegrotingsRegel.EGegeven.OnderhoudsCode);
                Guid rptid = _rapportService.RapportDataToevoegen(xmlText, (Guid)kostenbestandId, _Naam, MjobRapport.TypeOnderhoud);
                onderhoudsGegevens = _rapportService.RapportDataLezen(rptid, null, MjobRapport.TypeOnderhoud);
            }

            return onderhoudsGegevens;
        }

        public DataTable? HaalOnderhoudsGegevensUitDeCloud(Guid? kostenbestandId, int stuIndex)
        {
            DataTable? onderhoudsGegevens = null;
