        public void OngedaanMaken(BWijzigUmc opdracht)
        {
            _Umc_Private = !opdracht.Umc;
            if (!opdracht.Umc)
            {
                Debug.Assert(opdracht.Middelen != null, "BBegroting.OngedaanMaken(BWijzigUmc) - geen opdracht.m_Middelen");

                int stuIndex = -1;
                BKostenpost? ktp = _Stu.GeefVolgendeBgrRegel(EOnderbouwing.Kostenpost, ref stuIndex) as BKostenpost;
                while (ktp != null)
                {
                    BMiddel middel = ktp._Middel;
                    if (string.IsNullOrEmpty(middel._MidCde) == false)
                    {
                        if (!opdracht.Middelen.Contains(middel._Id))
                        {
                            // Dit is een duplicaat middel, het origineel heeft dezelfde middelcode
                            IDictionaryEnumerator de = opdracht.Middelen.GetEnumerator();
                            while (de.MoveNext())
                            {
                                BMiddel? zoekMiddel = de.Value as BMiddel;
                                if (zoekMiddel != null &&
                                   zoekMiddel._MidCde == middel._MidCde)
                                {
                                    ktp.WijzigMiddel(zoekMiddel, false);   // false: rekenen is niet nodig
                                    _Mid.MiddelVerwijderen(middel, true);  // true: er wordt nu iets ongedaan gemaakt
                                    break;
                                }
                            }
                        }
                    }
                    ktp = _Stu.GeefVolgendeBgrRegel(EOnderbouwing.Kostenpost, ref stuIndex) as BKostenpost;
                }
            }
        }
