        private void ControleerMeetstaten()
        {
            if (!_structuurStatusFout.Uitvoeren(EBegrotingControleStap.Meetstaten))
                return;

            LogboekMelding(ProjectResources.TradA0024126);
            bool controlerenEnRepareren = _structuurStatusFout.ControleerBegrotingStatus == EControleerBegrotingStatus.ControlerenEnRepareren;

            // stap 0: zijn er koppelingen die naar een begrotingsregel wijzen terwijl de begrotingsregel geen meetstaatkoppelingID of een andere heeft?
            BMeetstaatKoppeling msk_1, msk_2;
            int mskID;
            int stuIndex;
            IBegrotingsRegel? begrotingsRegel;

            bool maximaleNauwkeurigheid = _structuurStatusFout.Uitvoeren(EBegrotingControleStap.MaximaleNauwkeurigheid);
            int aantalDecimalen = maximaleNauwkeurigheid ? 5 : 3;

            if (_MeetstaatKoppelingen._Aantal > 0)
            {
                for (int mskIndex = _MeetstaatKoppelingen._Aantal - 1; mskIndex >= 0; mskIndex--)
                {
                    msk_1 = _MeetstaatKoppelingen[mskIndex];
                    if (msk_1._DocumentId <= 0)
                        continue;

                    stuIndex = _Stu.ZoekId(msk_1._DocumentId);
                    if (stuIndex <= 0)
                    {
                        _structuurStatusFout.VoegStatusToe(EStructuurStatusFout.MeetstaatKoppelingIntegriteit);
                        if (controlerenEnRepareren)
                        {
                            LogboekMelding(ProjectResources.TradMstNietbestaandeBgrRegelVerwijderd);
                            _MeetstaatKoppelingen.Verwijderen(msk_1);
                        }
                        else
                        {
                            LogboekMelding(ProjectResources.TradMstNietbestaandeBgrRegel);
                        }
                        continue;
                    }

                    _Stu.LeesBegrotingsRegel(stuIndex);
                    begrotingsRegel = _Stu[stuIndex]._Regel;
                    if (Math.Abs(begrotingsRegel?._MstKid ?? 0) != msk_1._KoppelingId)
                    {
                        _structuurStatusFout.VoegStatusToe(EStructuurStatusFout.MeetstaatKoppelingIntegriteit);
                        if (controlerenEnRepareren)
                        {
                            _MeetstaatKoppelingen.Verwijderen(mskIndex);
                            LogboekMelding(string.Format(ProjectResources.TradA00241273, msk_1._KoppelingId, stuIndex));
                        }
                        else
                        {
                            LogboekMelding(string.Format(ProjectResources.TradA00241274, msk_1._KoppelingId, stuIndex));
                        }
                    }
                    else
                    {
                        ControleerMeetstaten_GekoppeldeHvh(stuIndex, begrotingsRegel, aantalDecimalen);
                    }
                }

                // stap 1
                // Controleer of er dubbele meetstaatkoppelingen voorkomen.
                _voortgangsBalk.ZetAantalenMsg(0, _MeetstaatKoppelingen._Aantal, ProjectResources.TradA0024126, false, 0);
                int verwijderd = -1;

                int documentIDi, documentIDj;
                for (int mskIndex_1 = 0; mskIndex_1 < _MeetstaatKoppelingen._Aantal; mskIndex_1++)
                {
                    _voortgangsBalk.Perc(mskIndex_1);

                    msk_1 = _MeetstaatKoppelingen[mskIndex_1];

                    documentIDi = msk_1._DocumentId;
                    mskID = msk_1._KoppelingId;
                    for (int mskIndex_2 = 0; mskIndex_2 < _MeetstaatKoppelingen._Aantal; mskIndex_2++)
                    {
                        msk_2 = _MeetstaatKoppelingen[mskIndex_2];
                        documentIDj = msk_2._DocumentId;

                        // Als documentIDi of documentIDj 0 is dan geen melding geven. Dan gaat het over meetstaten die gekoppeld zijn aan het begrotingsblad
                        if (documentIDi == documentIDj && documentIDi != 0 && documentIDj != 0)
                        {
                            if (mskIndex_1 != mskIndex_2)
                            {

                                #region Controle welke verwijderd moet worden
                                int teVerwijderen = -1;

                                // Zoek via de structuurlijst naar de gekoppelde begrotingsregel
                                stuIndex = _Stu.ZoekId(msk_1._DocumentId);
                                // Als het documentid van deze 2 koppelingen hetzelfde is dan verder kijken.
                                // - 1) Als de overige gegevens mstid, klmid en rglid ook hetzelfde zijn dan kan ik ??n
                                //      van deze 2 zondermeer verwijderen: bij voorkeur die met de laagste (oudste) koppelingsid.
                                // - 2) Als deze gegevens NIET hetzelfde zijn dan kijken naar
                                //   2a) Welke hoeveelheid staat er bij de begrotingsregel.
                                //   2b) Bestaat gekoppelde meetstaat 1 met mstid, klmid en rglid
                                //   2c) Bestaat gekoppelde meetstaat 2 met mstid, klmid en rglid
                                //   2d) Komt deze hoeveelheid overeen met de hoeveelheid van de gekoppelde meetstaatcel
                                //   2e) Indien ok dan die met de laagste (oudste) koppelingsid verwijderen.

                                int bgrRegelNr;
                                if (stuIndex > 0)  // Gevonden?
                                {
                                    bgrRegelNr = stuIndex;
                                }
                                else
                                {
                                    if (controlerenEnRepareren)
                                    {
                                        LogboekMelding(string.Format(ProjectResources.TradA0024127 + BStatics.c_Spatie, msk_2, stuIndex, msk_1._DocumentId));
                                        _MeetstaatKoppelingen.Verwijderen(msk_2);
                                    }
                                    else
                                    {
                                        LogboekMelding(string.Format(ProjectResources.TradA0024127 + BStatics.c_Spatie, msk_2, stuIndex, msk_1._DocumentId));
                                    }
                                    continue;
                                }

                                if (msk_1._DocumentId == msk_2._DocumentId &&
                                   msk_1._KolomId == msk_2._KolomId &&
                                   msk_1._RegelId == msk_2._RegelId &&
                                   msk_1._MeetstaatId == msk_2._MeetstaatId)
                                {
                                    // 1) Als de overige gegevens mstid, klmid en rglid ook hetzelfde zijn dan kan ik ??n
                                    //    van deze 2 zondermeer verwijderen: bij voorkeur die met de laagste (oudste) koppeling
                                    if (msk_1._KoppelingId > msk_2._KoppelingId)
                                    {
                                        teVerwijderen = mskIndex_2;
                                    }
                                    else
                                    {
                                        teVerwijderen = mskIndex_1;
                                    }
                                }
                                else
                                {
                                    // - 2) Als deze gegevens NIET hetzelfde zijn dan kijken naar

                                    //   2a) Welke hoeveelheid staat er bij de begrotingsregel.
                                    bool geenWaardeBgr = true;
                                    double hvhBgr = _Stu[bgrRegelNr]._Regel is { } regelBgr
                                        ? regelBgr.GeefDouble(BBegrotingsRegel.EGegeven.hvh, out geenWaardeBgr)
                                        : 0.0;

                                    //   2b) Bestaat gekoppelde meetstaat 1 met mstid, klmid en rglid
                                    //   2c) Bestaat gekoppelde meetstaat 2 met mstid, klmid en rglid
                                    BMeetstaat? mst_1 = GeefMeetstaat(msk_1._MeetstaatId);
                                    BMeetstaat? mst_2 = GeefMeetstaat(msk_2._MeetstaatId);

                                    double hvh_1 = 0.0, hvh_2 = 0.0;
                                    bool geenWaarde_1 = false, geenWaarde_2 = false;
                                    if (mst_1 != null)
                                    {
                                        hvh_1 = mst_1.GeefGekoppeldeWaarde(msk_1, out geenWaarde_1);
                                    }
                                    if (mst_2 != null)
                                    {
                                        hvh_2 = mst_2.GeefGekoppeldeWaarde(msk_2, out geenWaarde_2);
                                    }

                                    // Nu bepalen welke verwijderd moet worden
                                    if (mst_1 == null || geenWaarde_1)
                                    {
                                        // Verwijder deze
                                        teVerwijderen = mskIndex_1;
                                    }
                                    else if (mst_2 == null || geenWaarde_2)
                                    {
                                        // Verwijder deze
                                        teVerwijderen = mskIndex_2;
                                    }
                                    if (teVerwijderen == -1)
                                    {
                                        // Ze bestaan beide: Nu kijken naar de hoeveelheden
                                        //   2d) Komt deze hoeveelheid overeen met de hoeveelheid van de gekoppelde meetstaatcel
                                        bool zelfdeHvh_1 = _statics.GetallenZijnGelijk(hvhBgr, hvh_1, 5);
                                        bool zelfdeHvh_2 = _statics.GetallenZijnGelijk(hvhBgr, hvh_2, 5);
                                        if (!zelfdeHvh_1 && !zelfdeHvh_2)
                                        {
                                            // Verwijder de laagste koppelingid
                                            if (msk_1._KoppelingId > msk_2._KoppelingId)
                                            {
                                                teVerwijderen = mskIndex_2;
                                            }
                                            else
                                            {
                                                teVerwijderen = mskIndex_1;
                                            }
                                        }
                                        else if (zelfdeHvh_1)
                                        {
                                            teVerwijderen = mskIndex_2;
                                        }
                                        else
                                        {
                                            teVerwijderen = mskIndex_1;
                                        }

                                    }
                                }
                                #endregion Controle welke verwijderd moet worden

                                _structuurStatusFout.VoegStatusToe(EStructuurStatusFout.MeetstaatKoppelingIntegriteit);
                                if (controlerenEnRepareren)
                                {
                                    int koppelId;
                                    if (teVerwijderen == mskIndex_1)
                                    {
                                        _MeetstaatKoppelingen.Verwijderen(msk_1);
                                        koppelId = msk_2._KoppelingId;
                                    }
                                    else
                                    {
                                        _MeetstaatKoppelingen.Verwijderen(msk_2);
                                        koppelId = msk_1._KoppelingId;
                                    }

                                    if (_Stu[stuIndex]._Regel != null &&
                                        _Stu[stuIndex]._Regel?._MstKid != koppelId)
                                    {
                                        _Stu[stuIndex]._Regel?._MstKid = koppelId;
                                        _Stu[stuIndex]._Regel?.ZetMutatieStatus(BewaarItemMutatieStatus.Gewijzigd);
                                    }

                                    LogboekMelding(string.Format(ProjectResources.TradA00241271, mskID, bgrRegelNr));
                                    verwijderd = teVerwijderen;
                                }
                                else
                                {
                                    LogboekMelding(string.Format(ProjectResources.TradA00241272, mskID, bgrRegelNr));
                                }
                            }
                        }
                    }
                    if (controlerenEnRepareren)
                    {
                        if (verwijderd == mskIndex_1) //de volgende koppeling is eentje lager
                            mskIndex_1--;
                        verwijderd = -1;
                    }
                }

                // stap 2
                // Controleer of er meetstaatkoppelingen zijn die niet in de begroting voorkomen.

                for (int i = 0; i < _MeetstaatKoppelingen._Aantal; i++)
                {
                    _voortgangsBalk.Perc(i);
                    BMeetstaatKoppeling mstk = _MeetstaatKoppelingen[i];
                    if (ZoekGekoppeldeBegrotingsRegel(mstk) == null && ZoekGekoppeldeBegrotingsbladRegel(mstk) == null)
                    {
                        int koppelingId = mstk._KoppelingId;
                        int regelNr = mstk._RegelNr;

                        _structuurStatusFout.VoegStatusToe(EStructuurStatusFout.MeetstaatKoppelingIntegriteit);

                        //verwijder de meetstaat koppeling, als de parameter op direct herstellen staat.
                        if (controlerenEnRepareren)
                        {
                            _MeetstaatKoppelingen.Verwijderen(mstk);
                            i--;

                            LogboekMelding(string.Format(ProjectResources.TradA00241273, koppelingId, regelNr));
                        }
                        else
                        {
                            LogboekMelding(string.Format(ProjectResources.TradA00241274, koppelingId, regelNr));
                        }
                    }
                }
            }


            for (stuIndex = 0; stuIndex < _Stu._Aantal; stuIndex++)
            {
                _voortgangsBalk.Perc(stuIndex);
                if (_Stu[stuIndex]._Tpe == EOnderbouwing.Element ||
                   _Stu[stuIndex]._Tpe == EOnderbouwing.Kostenpost)
                {
                    // stap 3
                    // Controleer of er meetstaatkoppelingen in de begroting voorkomen
                    // die niet in de meetstaatkoppelingen voorkomen
                    IBegrotingsRegel? bgrRegel = _Stu[stuIndex]._Regel as BBegrotingsRegel;
                    if (bgrRegel != null && bgrRegel._MstKid != 0)
                    {
                        BMeetstaatKoppeling? koppeling = ZoekMeetstaatKoppeling(bgrRegel._MstKid);
                        if (null == koppeling)
                        {
                            _structuurStatusFout.VoegStatusToe(EStructuurStatusFout.MeetstaatKoppelingIntegriteit);
                            if (controlerenEnRepareren)
                            {
                                LogboekMelding(string.Format(ProjectResources.TradA00241275, bgrRegel._Id, stuIndex, bgrRegel._MstKid));
                                bgrRegel.MeetstaatKoppeling(null);
                            }
                            else
                            {
                                LogboekMelding(string.Format(ProjectResources.TradA00241276, bgrRegel._Id, stuIndex, bgrRegel._MstKid));
                            }
                        }
                    }
                }
            }


            // stap 4
            // Meetstaten met 0 regels verwijderen
            for (int mstIndex = _Meetstaten.Count - 1; mstIndex > 0; mstIndex--)
            {
                _voortgangsBalk.Perc(mstIndex);
                IMeetstaat meetstaat = _Meetstaten[mstIndex];
                LeesMeetstaat(meetstaat);
                if (meetstaat.AantalRijen() == 0)
                {
                    _structuurStatusFout.VoegStatusToe(EStructuurStatusFout.MeetstaatNulRegels);
                    string msg;
                    if (controlerenEnRepareren)
                    {
                        msg = string.Format(ProjectResources.TradA00241277, meetstaat._Id);
                        _VerwijderdeMeetstaten.Add(meetstaat);
                        _Meetstaten.Remove(meetstaat);
                        //begroting.VerhoogMeetstaatVersie();??? even aan SB vragen
                    }
                    else
                    {
                        msg = string.Format(ProjectResources.TradA00241278, meetstaat._Id);
                    }
                    LogboekMelding(msg);
                }
            }

            bool ControleNogEenKeer = false;

            // Stap 5 
            // Controleer of er meetstaatkoppelingen zijn die niet in meetstaten voorkomen
            for (int i = 0; i < _MeetstaatKoppelingen._Aantal; i++)
            {
                _voortgangsBalk.Perc(i);
                BMeetstaatKoppeling mstk = _MeetstaatKoppelingen[i];

                if (null == GeefMeetstaat(mstk._MeetstaatId))
                {
                    _structuurStatusFout.VoegStatusToe(EStructuurStatusFout.MeetstaatKoppelingIntegriteit);
                    if (controlerenEnRepareren)
                    {
                        _MeetstaatKoppelingen.Verwijderen(mstk);
                        LogboekMelding(string.Format(ProjectResources.TradA00241279, mstk._KoppelingId));
                        ControleNogEenKeer = true;
                    }
                    else
                    {
                        LogboekMelding(string.Format(ProjectResources.TradA002412710, mstk._KoppelingId));
                    }
                }
            }

            if (ControleNogEenKeer)
                _structuurStatusFout.VoegStatusToe(EStructuurStatusFout.Verstoord);
        }

        private void ControleerMeetstaten_GekoppeldeHvh(int stuIndex, IBegrotingsRegel? begrotingsRegel, int aantalDecimalen)
        {
            if (begrotingsRegel == null) return;
            if (begrotingsRegel._MstKid == 0)
                return;

            bool controlerenEnRepareren = _structuurStatusFout.ControleerBegrotingStatus == EControleerBegrotingStatus.ControlerenEnRepareren;

            BMeetstaat? meetstaat = GeefMeetstaat(begrotingsRegel, out BMeetstaatKoppeling? meetstaatKoppeling);
            if (meetstaatKoppeling == null || meetstaat == null)
            {
                _structuurStatusFout.VoegStatusToe(EStructuurStatusFout.MeetstaatKoppelingIntegriteit);
                if (controlerenEnRepareren)
                {
                    LogboekMelding(string.Format(ProjectResources.TradA00241275, begrotingsRegel._Id, stuIndex, begrotingsRegel._MstKid));
                    begrotingsRegel.MeetstaatKoppeling(null);
                }
                else
                {
                    LogboekMelding(string.Format(ProjectResources.TradA00241276, begrotingsRegel._Id, stuIndex, begrotingsRegel._MstKid));
                }
                return;
            }

            if (begrotingsRegel._MstKid < 0)
                return;

            double hvhBgr = begrotingsRegel.GeefDouble(BBegrotingsRegel.EGegeven.hvh, out bool geenWaardeBgr);
            if (geenWaardeBgr)
                return;

            double hvhMst = meetstaat.GeefGekoppeldeWaarde(meetstaatKoppeling, out bool geenWaardeMst);
            if (geenWaardeMst)
                return;

            if (_statics.GetallenZijnGelijk(hvhBgr, hvhMst, aantalDecimalen))
                return;

            _structuurStatusFout.VoegStatusToe(EStructuurStatusFout.MeetstaatKoppelingIntegriteit);
            if (controlerenEnRepareren)
            {
                // Op regel {0} van de begroting is de hoeveelheid ({1:0.#####}) gelijkgemaakt aan de gekoppelde waarde in de meetstaat ({2:0.#####})
                LogboekMelding(begrotingsRegel, string.Format(ProjectResources.TradBgrHvhNuGelijkAanMstHvh, stuIndex, hvhBgr, hvhMst));
                begrotingsRegel.WijzigDouble(BBegrotingsRegel.EGegeven.hvh, hvhMst);
                begrotingsRegel.MeetstaatKoppeling(meetstaatKoppeling);
            }
            else
            {
                // Op regel {0} van de begroting komt de hoeveelheid ({1:0.#####}) niet overeen met de gekoppelde waarde in de meetstaat ({2:0.#####})
                LogboekMelding(begrotingsRegel, string.Format(ProjectResources.TradBgrHvhOngelijkMstHvh, stuIndex, hvhBgr, hvhMst));
            }
        }

