        private int ControleerMiddelen()
        {
            if (!_structuurStatusFout.Uitvoeren(EBegrotingControleStap.Middelen))
                return 0;

            LogboekMelding(ProjectResources.TradA002412714);

            int gewijzigd = 0;
            _voortgangsBalk.ZetAantalenMsg(0, _Stu._Aantal, ProjectResources.TradA002412715, false, 0);
            EControleerBegrotingStatus controleerBegrotingStatus = _structuurStatusFout.ControleerBegrotingStatus;

            for (int stuIndex = 0; stuIndex < _Stu._Aantal; stuIndex++)
            {
                _voortgangsBalk.Perc(stuIndex);
                if (_Stu[stuIndex]._Tpe == EOnderbouwing.Kostenpost)
                {
                    _Stu.LeesBegrotingsRegel(stuIndex);
                    int kostenpostId = _Stu[stuIndex]._Id;
                    var kostenpost = _Stu[stuIndex]._Regel as BKostenpost;
                    if (kostenpost == null)
                    {
                        if (controleerBegrotingStatus == EControleerBegrotingStatus.ControlerenEnRepareren)
                        {
                            kostenpost = MaakNieuweKostenpost(stuIndex) as BKostenpost;  //logboek message staat in MaakNieuweKostenpost()
                            kostenpostId = kostenpost?._Id ?? _Stu[stuIndex]._Id;
                            _structuurStatusFout.VoegStatusToe(EStructuurStatusFout.Kostenpost);
                        }
                        else
                        {
                            LogboekMelding(string.Format(ProjectResources.TradA002412716, _Stu[stuIndex]._Id, stuIndex));
                        }
                    }

                    if (kostenpost?._Middel == null)
                    {
                        if (controleerBegrotingStatus == EControleerBegrotingStatus.Controleren)
                        {
                            // Zie andere logboekmelding bij s_DirektHerstellen in de functie:BMiddel GeefMiddel(int midId, int ktpId) 
                            LogboekMelding(string.Format(ProjectResources.TradA002412717, kostenpostId, stuIndex));
                        }
                        else
                        {
                            MaakOntbrekendMiddel(kostenpost);
                        }
                        _structuurStatusFout.VoegStatusToe(EStructuurStatusFout.Middel);
                    }
                }
            }
            return gewijzigd;
        }

        private void ControleerParents()
        {
            if (!_structuurStatusFout.Uitvoeren(EBegrotingControleStap.Parents))
                return;

            LogboekMelding(ProjectResources.TradA002412718);
            _voortgangsBalk.ZetAantalenMsg(0, _Stu._Aantal, ProjectResources.TradA002412719, false, 0);

            for (int stuIndex = 0; stuIndex < _Stu._Aantal; stuIndex++)
            {
                try
                {
                    _voortgangsBalk.Perc(stuIndex);
                    _Stu.LeesBegrotingsRegel(stuIndex);
                    if (_Stu[stuIndex]._Regel == null)
                        _structuurStatusFout.VoegStatusToe(EStructuurStatusFout.Verstoord);
                }
                catch (Exception ex)
                {
                    _logger.LogExceptionWithMessage(ex);

                    // Fouten in dit stadium niet van belang, deze controle vindt later plaats
                    _structuurStatusFout.VoegStatusToe(EStructuurStatusFout.Verstoord);
                    return;
                }

                int parentid = _Stu[stuIndex]._PrtId;
                if (parentid != 0)
                {
                    int zoekIndex = _Stu.ZoekElement(parentid, stuIndex);
                    if (zoekIndex < 0 || zoekIndex >= stuIndex)
                    {
                        if (_structuurStatusFout.ControleerBegrotingStatus == EControleerBegrotingStatus.Controleren)
                            LogboekMelding(string.Format(ProjectResources.TradA002412720,
                               _Stu[stuIndex]._Id, stuIndex, parentid));

                        _structuurStatusFout.VoegStatusToe(EStructuurStatusFout.VerkeerdParentId);
                    }
                }
            }
        }

