        public bool BgrHeeftOpslagposten(int controle)
        {
            // Controle:
            //  0: zijn er opslagposten in de begroting?
            //  1: zijn er opslagposten in de begroting van type elementtussentotaal?
            //  2: zijn er opslagposten in de begroting met een opslag per kostensoort?

            int stuIndex = -1;
            BOpslagpost? regel = _Stu.GeefVolgendeBgrRegel(EOnderbouwing.Opslagpost, ref stuIndex) as BOpslagpost;
            while (regel != null)
            {
                switch (controle)
                {
                    case 0:
                        return true;

                    case 1:
                        if (regel._IsElementTussentotaal)
                            return true;
                        break;

                    case 2:
                        if (!regel._IsNormaleOpslag && !regel._IsSubtotaalOpslag)
                            break;
                        if (!_statics.IsNul(regel._PctArb)
                            || !_statics.IsNul(regel._PctMta)
                            || !_statics.IsNul(regel._PctMte)
                            || !_statics.IsNul(regel._PctOda))
                            return true;
                        break;
                }
                regel = _Stu.GeefVolgendeBgrRegel(EOnderbouwing.Opslagpost, ref stuIndex) as BOpslagpost;
            }

            return false;
        }
