    /// <summary>
    /// Tel de bedragen in de gegeven BXtoKst op bij de huidige
    /// </summary>
    /// <param name="xtokst">De op te tellen bedragen</param>
    internal void Optellen(BXtoKst xtokst, bool inclusiefBtw)
    {
        if (m_Vlt != xtokst.m_Vlt)
        {
            for (int index = c_AtlKst - 1; index >= 0; index--)
            {
                m_XtoKst[(int)EXto.Nto, index] += BBedrag.Converteer(xtokst.m_Vlt, xtokst.m_XtoKst[(int)EXto.Nto, index], m_Vlt, m_ValutaVzl);
                m_XtoKst[(int)EXto.Bto, index] += xtokst.m_XtoKst[(int)EXto.Bto, index];
                
                if (inclusiefBtw)
                {
                    m_XtoKst[(int)EXto.Bgh, index] += xtokst.m_XtoKst[(int)EXto.Bgh, index];
                    m_XtoKst[(int)EXto.Bgl, index] += xtokst.m_XtoKst[(int)EXto.Bgl, index];
                }
            }
        }
        else
        {
            for (int index = c_AtlKst - 1; index >= 0; index--)
            {
                m_XtoKst[(int)EXto.Nto, index] += xtokst.m_XtoKst[(int)EXto.Nto, index];
                m_XtoKst[(int)EXto.Bto, index] += xtokst.m_XtoKst[(int)EXto.Bto, index];
                if (inclusiefBtw)
                {
                    m_XtoKst[(int)EXto.Bgh, index] += xtokst.m_XtoKst[(int)EXto.Bgh, index];
                    m_XtoKst[(int)EXto.Bgl, index] += xtokst.m_XtoKst[(int)EXto.Bgl, index];
                }
            }
        }
    }
    /// <summary>
    /// Tel de bedragen in de gegeven BXtoKst op bij de huidige
    /// </summary>
    /// <param name="xtoDoel">Bruto of netto van huidig object</param>
    /// <param name="xtokst">De op te tellen bedragen</param>
    /// <param name="xto">Bruto of netto van op te tellen bedragen</param>
    public void Optellen(EXto xtoDoel, BXtoKst xtokst, EXto xto)
    {
        if (m_Vlt != xtokst.m_Vlt)
            throw new OngelijkeValutaException();

        for (int index = c_AtlKst - 1; index >= 0; index--)
        {
            m_XtoKst[(int)xtoDoel, index] += xtokst.m_XtoKst[(int)xto, index];
        }
    }

    public void Optellen(BBdrKst bdrkst, EXto xto)
    {
        for (int index = c_AtlKst - 1; index >= 0; index--)
        {
            m_XtoKst[(int)xto, index] += bdrkst[(EKst)index].Waarde;
        }
    }

    /// <summary>
    /// Trek de bedragen in de gegeven BXtoKst af van de huidige
    /// </summary>
    /// <param name="xtokst">De af te trekken bedragen</param>
    public void Aftrekken(BXtoKst xtokst, bool inclusiefBtw)
    {
        if (m_Vlt != xtokst.m_Vlt)
            throw new OngelijkeValutaException();

        for (int index = c_AtlKst - 1; index >= 0; index--)
        {
            m_XtoKst[(int)EXto.Nto, index] -= xtokst.m_XtoKst[(int)EXto.Nto, index];
            m_XtoKst[(int)EXto.Bto, index] -= xtokst.m_XtoKst[(int)EXto.Bto, index];

            if (inclusiefBtw)
            {
                m_XtoKst[(int)EXto.Bgh, index] -= xtokst.m_XtoKst[(int)EXto.Bgh, index];
                m_XtoKst[(int)EXto.Bgl, index] -= xtokst.m_XtoKst[(int)EXto.Bgl, index];
            }
        }
    }
    /// <summary>
