    public bool VeldInteger(int kolomNr, int rijNr, int waarde)
    {
        int stuIndex = StuIndex(rijNr);
        if (AlleenLezen())
        {
            m_Structuur[stuIndex]._Regel.VerversUi();
            return true;
        }

        m_Structuur.LeesBegrotingsRegel(stuIndex);
        BOpdracht? opdracht = m_Begroting.WijzigIntegerBgrRegel(stuIndex, (EGegeven)kolomNr, waarde);
